def ejecutores(apps, schema_editor):
    """Cada visita existente pasa a tener a su técnico como ejecutor (equipo unipersonal)."""
    Intento = apps.get_model("operaciones", "Intento")
    P = apps.get_model("operaciones", "ParticipacionVisita")
    P.objects.bulk_create([P(intento_id=i, persona_id=t, funcion="ejecutor", minutos=m) for i, t, m in
                           Intento.objects.filter(tecnico__isnull=False).values_list("id", "tecnico_id", "minutos_reales")
                           .iterator(chunk_size=5000)], batch_size=5000)


